/**
 * Full-catalog generator.
 *
 * Reads the REAL manifest.json and claims every entry exactly once:
 *   1. First, via existing curated structures that already resolve to it
 *      (lib/data/anatomy/*.ts) — their hand-written name/description win.
 *   2. Anything left over becomes an auto-generated KeyStructure whose
 *      `id` IS the manifest key (so it always resolves via the resolver's
 *      exact-match tier — no alias guessing needed) and whose name is
 *      derived from the key by de-kebab-casing it. Description is a
 *      neutral, factual statement about provenance — never an invented
 *      medical claim.
 *
 * Auto-generated entries for manifest "system" values that don't already
 * have a curated AnatomySystem (e.g. regions, joints, lymphoid, visceral)
 * get a minimal auto-built AnatomySystem too.
 *
 * Usage:
 *   npm run generate-catalog
 *
 * Outputs:
 *   lib/data/generatedCatalog.ts  — consumed by lib/data/anatomy/index.ts
 *   scripts/catalog-report.md     — what was claimed, generated, or flagged
 */

import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { ANATOMY_SYSTEMS as CURATED_SYSTEMS } from "../lib/data/anatomy";
import { resolveModel } from "../lib/modelResolver";
import type { AnatomySystem, KeyStructure } from "../lib/data/anatomy/types";
import type { Manifest } from "../lib/manifest";

const ROOT = path.resolve(__dirname, "..");
const MANIFEST_PATH = path.join(ROOT, "public/models/manifest.json");
const OUTPUT_PATH = path.join(ROOT, "lib/data/generatedCatalog.ts");
const REPORT_PATH = path.join(ROOT, "scripts/catalog-report.md");

const CURATED_SYSTEM_IDS = new Set(CURATED_SYSTEMS.map((s) => s.id));

// Honest, general, non-fabricated descriptions of what each classification
// bucket MEANS — not medical claims about any specific structure.
const NEW_SYSTEM_DESCRIPTIONS: Record<string, string> = {
  regions:
    "Topological body regions spanning multiple organ systems, as classified by the Z-Anatomy dataset.",
  joints:
    "Articulations and connective structures between bones, as classified by the Z-Anatomy dataset.",
  lymphoid: "Lymph nodes, vessels, and related tissue, as classified by the Z-Anatomy dataset.",
  visceral: "Internal organs grouped together, as classified by the Z-Anatomy dataset.",
  unclassified:
    "Structures the export pipeline could not automatically classify into a specific body system.",
};

function loadManifest(): Manifest {
  const raw = readFileSync(MANIFEST_PATH, "utf-8");
  const data: unknown = JSON.parse(raw);
  if (typeof data !== "object" || data === null || Array.isArray(data)) {
    throw new Error(`${MANIFEST_PATH} is not a valid manifest object`);
  }
  return data as Manifest;
}

const STOPWORDS = new Set(["of", "the", "and", "in", "on", "for", "to"]);

/** "bones-of-free-lower-limb" -> "Bones of Free Lower Limb" */
function humanizeKey(key: string): string {
  return key
    .split("-")
    .filter(Boolean)
    .map((word, index) => {
      if (index > 0 && STOPWORDS.has(word)) return word;
      return word.charAt(0).toUpperCase() + word.slice(1);
    })
    .join(" ");
}

function humanizeSystemId(id: string): string {
  return humanizeKey(id)
    .split(" ")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

interface GenerationResult {
  additionalStructuresBySystem: Record<string, KeyStructure[]>;
  generatedSystems: AnatomySystem[];
  claimedByCurated: number;
  autoGeneratedIntoExisting: number;
  autoGeneratedNewSystems: Record<string, number>;
  flagged: Array<{ key: string; reason: string }>;
}

function generate(manifest: Manifest): GenerationResult {
  const claimedKeys = new Set<string>();

  // Step 1: claim every manifest key already reachable via curated data.
  for (const system of CURATED_SYSTEMS) {
    for (const structure of system.keyStructures) {
      const resolved = resolveModel(manifest, structure);
      if (resolved) claimedKeys.add(resolved.id);
    }
  }
  const claimedByCurated = claimedKeys.size;

  const additionalStructuresBySystem: Record<string, KeyStructure[]> = {};
  const newSystemStructures: Record<string, KeyStructure[]> = {};
  const flagged: GenerationResult["flagged"] = [];
  let autoGeneratedIntoExisting = 0;

  // Step 2: claim everything else, deterministically, once each.
  for (const [key, entry] of Object.entries(manifest)) {
    if (claimedKeys.has(key)) continue;
    claimedKeys.add(key);

    if (!entry || typeof entry.system !== "string" || entry.system.length === 0) {
      flagged.push({ key, reason: "Manifest entry has no valid system value — skipped." });
      continue;
    }

    const generatedStructure: KeyStructure = {
      id: key,
      name: humanizeKey(key),
      description: "Exported from the Z-Anatomy dataset.",
    };

    if (CURATED_SYSTEM_IDS.has(entry.system)) {
      (additionalStructuresBySystem[entry.system] ??= []).push(generatedStructure);
      autoGeneratedIntoExisting++;
    } else {
      (newSystemStructures[entry.system] ??= []).push(generatedStructure);
    }
  }

  const generatedSystems: AnatomySystem[] = Object.entries(newSystemStructures).map(
    ([systemId, structures]) => ({
      id: systemId,
      name: `${humanizeSystemId(systemId)} System`,
      shortName: humanizeSystemId(systemId),
      description:
        NEW_SYSTEM_DESCRIPTIONS[systemId] ??
        `Structures classified under "${systemId}" by the Z-Anatomy dataset.`,
      keyStructures: structures,
      quickFacts: [],
      imagingAvailability: ["3D Anatomy"],
      relatedSystemIds: [],
    }),
  );

  const autoGeneratedNewSystems = Object.fromEntries(
    Object.entries(newSystemStructures).map(([id, list]) => [id, list.length]),
  );

  return {
    additionalStructuresBySystem,
    generatedSystems,
    claimedByCurated,
    autoGeneratedIntoExisting,
    autoGeneratedNewSystems,
    flagged,
  };
}

function writeGeneratedFile(result: GenerationResult): void {
  const lines = [
    "/**",
    " * AUTO-GENERATED by scripts/generate-catalog.ts — do not hand-edit.",
    " * Regenerate with: npm run generate-catalog",
    " *",
    " * Merged into ANATOMY_SYSTEMS by lib/data/anatomy/index.ts. Every",
    " * structure here has an `id` equal to a real manifest key, so it",
    " * always resolves — nothing here is a guess.",
    " */",
    "",
    'import type { AnatomySystem, KeyStructure } from "./anatomy/types";',
    "",
    "export const GENERATED_STRUCTURES_BY_SYSTEM: Record<string, KeyStructure[]> = ",
    JSON.stringify(result.additionalStructuresBySystem, null, 2) + ";",
    "",
    "export const GENERATED_SYSTEMS: AnatomySystem[] = ",
    JSON.stringify(result.generatedSystems, null, 2) + ";",
    "",
  ];
  writeFileSync(OUTPUT_PATH, lines.join("\n"), "utf-8");
}

function writeReport(manifest: Manifest, result: GenerationResult): void {
  const total = Object.keys(manifest).length;
  const newSystemTotal = Object.values(result.autoGeneratedNewSystems).reduce((a, b) => a + b, 0);

  const lines: string[] = [
    "# Catalog generation report",
    "",
    `Generated: ${new Date().toISOString()}`,
    "",
    `- Manifest entries total: ${total}`,
    `- Claimed by existing curated structures: ${result.claimedByCurated}`,
    `- Auto-generated into existing systems: ${result.autoGeneratedIntoExisting}`,
    `- Auto-generated into new systems: ${newSystemTotal}`,
    `- Flagged (invalid/unrepresentable): ${result.flagged.length}`,
    "",
  ];

  if (Object.keys(result.autoGeneratedNewSystems).length > 0) {
    lines.push("## New systems created", "", "| System | Structures |", "| --- | --- |");
    for (const [id, count] of Object.entries(result.autoGeneratedNewSystems)) {
      lines.push(`| ${id} | ${count} |`);
    }
    lines.push("");
  }

  if (result.flagged.length > 0) {
    lines.push(
      "## Flagged — not safely representable",
      "",
      "| Manifest key | Reason |",
      "| --- | --- |",
    );
    for (const f of result.flagged) {
      lines.push(`| \`${f.key}\` | ${f.reason} |`);
    }
    lines.push("");
  }

  writeFileSync(REPORT_PATH, lines.join("\n"), "utf-8");
}

function main(): void {
  const manifest = loadManifest();
  const result = generate(manifest);

  writeGeneratedFile(result);
  writeReport(manifest, result);

  const newSystemTotal = Object.values(result.autoGeneratedNewSystems).reduce((a, b) => a + b, 0);

  console.log(`Manifest entries              : ${Object.keys(manifest).length}`);
  console.log(`Claimed by curated structures  : ${result.claimedByCurated}`);
  console.log(`Auto-generated (existing sys)  : ${result.autoGeneratedIntoExisting}`);
  console.log(`Auto-generated (new systems)   : ${newSystemTotal}`);
  console.log(`Flagged                        : ${result.flagged.length}`);
  console.log(`Report written to              : ${REPORT_PATH}`);
  console.log(`Catalog written to             : ${OUTPUT_PATH}`);
}

main();
